import type { Finding, Report } from '../../src/missions/types';

/** A hand-made report with one finding of each category and one safe look-alike. Used by the missions tests. */
const f = (x: Partial<Finding> & Pick<Finding, 'id' | 'category' | 'severity' | 'rule' | 'title' | 'path' | 'context' | 'flags'>): Finding => ({
  startLine: x.flags[0]?.start ?? x.context.startLine,
  endLine: x.flags[x.flags.length - 1]?.end ?? x.context.startLine,
  decoys: [],
  fix: { summary: 'Apply the recommended fix.' },
  evidence: '',
  owned: false,
  ...x,
});

